/**
 * Tests for bin/analytics-rotate.mjs, the shared analytics rotation helper.
 *
 * WHY THESE EXIST
 *
 *   #3151 bounded hook-timing.jsonl and shipped ZERO tests for the helper it
 *   added (its commit message claimed "7 direct assertions"; `git grep
 *   rotateAnalyticsIfNeeded` matched no test file). The two behaviours it got
 *   wrong are exactly the two that are untestable by inspection:
 *
 *     1. rotation with no archive retention, so 99% of the bytes just moved to
 *        a filename nothing capped (300 MB archive vs 236 KB active file);
 *     2. a same-month rotation renaming onto an existing archive, destroying it
 *        silently.
 *
 *   These run against a REAL temp directory rather than a mocked node:fs. The
 *   defects are filesystem-state defects (which file exists, how many, how
 *   large, which one got deleted); a call-shape assertion on a renameSync mock
 *   is exactly what let them ship.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync, readFileSync, readdirSync, existsSync, utimesSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { rotateAnalyticsIfNeeded, pruneArchives } from '../../../bin/analytics-rotate.mjs';

let dir: string;

/** Write a file of exactly `bytes` length whose content is identifiable. */
function writeSized(path: string, bytes: number, marker = 'x'): void {
  writeFileSync(path, marker.repeat(bytes));
}

/** Force a deterministic mtime so oldest-first pruning is not clock-racy. */
function setMtime(path: string, epochSeconds: number): void {
  utimesSync(path, epochSeconds, epochSeconds);
}

/** Archive files for hook-timing, sorted for stable assertions. */
function archives(): string[] {
  return readdirSync(dir)
    .filter((f) => /^hook-timing\.\d{4}-\d{2}(\.\d+)?\.jsonl$/.test(f))
    .sort();
}

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'ork-rotate-'));
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

describe('rotateAnalyticsIfNeeded', () => {
  it('leaves a file under the cap untouched', () => {
    const active = join(dir, 'hook-timing.jsonl');
    writeSized(active, 100);

    rotateAnalyticsIfNeeded(active, { maxBytes: 1000 });

    expect(existsSync(active)).toBe(true);
    expect(readFileSync(active, 'utf8')).toHaveLength(100);
    expect(archives()).toEqual([]);
  });

  it('does not rotate a file exactly at the cap (cap is exclusive)', () => {
    const active = join(dir, 'hook-timing.jsonl');
    writeSized(active, 1000);

    rotateAnalyticsIfNeeded(active, { maxBytes: 1000 });

    expect(archives()).toEqual([]);
    expect(existsSync(active)).toBe(true);
  });

  it('rotates once the file exceeds the cap', () => {
    const active = join(dir, 'hook-timing.jsonl');
    writeSized(active, 1001);

    rotateAnalyticsIfNeeded(active, { maxBytes: 1000 });

    expect(existsSync(active)).toBe(false);
    const found = archives();
    expect(found).toHaveLength(1);
    expect(found[0]).toMatch(/^hook-timing\.\d{4}-\d{2}\.jsonl$/);
    expect(readFileSync(join(dir, found[0]), 'utf8')).toHaveLength(1001);
  });

  it('does NOT clobber an existing archive on a second same-month rotation', () => {
    const active = join(dir, 'hook-timing.jsonl');

    writeSized(active, 1001, 'a');
    rotateAnalyticsIfNeeded(active, { maxBytes: 1000 });

    writeSized(active, 1001, 'b');
    rotateAnalyticsIfNeeded(active, { maxBytes: 1000 });

    const found = archives();
    expect(found).toHaveLength(2);

    // Both payloads survive: the first rotation's bytes were not overwritten.
    const contents = found.map((f) => readFileSync(join(dir, f), 'utf8')[0]).sort();
    expect(contents).toEqual(['a', 'b']);
  });

  it('keeps discriminating archives beyond the second same-month rotation', () => {
    const active = join(dir, 'hook-timing.jsonl');

    for (const marker of ['a', 'b', 'c']) {
      writeSized(active, 1001, marker);
      rotateAnalyticsIfNeeded(active, { maxBytes: 1000, maxArchives: 10 });
    }

    const found = archives();
    expect(found).toHaveLength(3);
    const contents = found.map((f) => readFileSync(join(dir, f), 'utf8')[0]).sort();
    expect(contents).toEqual(['a', 'b', 'c']);
  });

  it('prunes oldest archives once the count cap is exceeded', () => {
    const active = join(dir, 'hook-timing.jsonl');

    // Four rotations with a cap of 2 archives.
    const markers = ['a', 'b', 'c', 'd'];
    markers.forEach((marker, i) => {
      writeSized(active, 1001, marker);
      rotateAnalyticsIfNeeded(active, { maxBytes: 1000, maxArchives: 2 });
      // Age each archive deterministically so oldest-first is unambiguous.
      for (const f of archives()) {
        if (readFileSync(join(dir, f), 'utf8')[0] === marker) {
          setMtime(join(dir, f), 1_000_000 + i * 1000);
        }
      }
    });

    const found = archives();
    expect(found).toHaveLength(2);
    const contents = found.map((f) => readFileSync(join(dir, f), 'utf8')[0]).sort();
    expect(contents).toEqual(['c', 'd']); // 'a' and 'b' were the oldest
  });

  it('prunes on total archive bytes even when the count cap is satisfied', () => {
    const active = join(dir, 'hook-timing.jsonl');

    writeSized(active, 1001, 'a');
    rotateAnalyticsIfNeeded(active, { maxBytes: 1000, maxArchives: 10, maxArchiveBytes: 10 ** 9 });
    setMtime(join(dir, archives()[0]), 1_000_000);

    writeSized(active, 1001, 'b');
    // Byte cap of 1500 admits one 1001-byte archive but not two.
    rotateAnalyticsIfNeeded(active, { maxBytes: 1000, maxArchives: 10, maxArchiveBytes: 1500 });

    const found = archives();
    expect(found).toHaveLength(1);
    expect(readFileSync(join(dir, found[0]), 'utf8')[0]).toBe('b');
  });

  it('never prunes the archive the current rotation just created', () => {
    const active = join(dir, 'hook-timing.jsonl');
    writeSized(active, 1001, 'a');

    // Both caps are impossible to satisfy; the newest archive must still survive
    // or rotation would destroy the very data it moved.
    rotateAnalyticsIfNeeded(active, { maxBytes: 1000, maxArchives: 0, maxArchiveBytes: 0 });

    const found = archives();
    expect(found).toHaveLength(1);
    expect(readFileSync(join(dir, found[0]), 'utf8')[0]).toBe('a');
  });

  it('prunes a pre-existing oversized archive left by the unbounded era', () => {
    // Reproduces the reported state: a 300 MB rotated archive next to a tiny
    // active file, scaled down. The next rotation must reclaim it.
    const active = join(dir, 'hook-timing.jsonl');
    const legacy = join(dir, 'hook-timing.2026-07.jsonl');
    writeSized(legacy, 50_000, 'L');
    setMtime(legacy, 1_000_000);

    writeSized(active, 1001, 'n');
    rotateAnalyticsIfNeeded(active, { maxBytes: 1000, maxArchives: 5, maxArchiveBytes: 5000 });

    const found = archives();
    expect(found).toHaveLength(1);
    expect(readFileSync(join(dir, found[0]), 'utf8')[0]).toBe('n');
    expect(existsSync(legacy)).toBe(false);
  });

  it('ignores unrelated files in the analytics directory', () => {
    const active = join(dir, 'hook-timing.jsonl');
    const sibling = join(dir, 'agent-usage.2026-01.jsonl');
    const notes = join(dir, 'hook-timing-notes.txt');
    writeSized(sibling, 5000, 's');
    writeSized(notes, 5000, 'n');

    writeSized(active, 1001, 'a');
    rotateAnalyticsIfNeeded(active, { maxBytes: 1000, maxArchives: 1, maxArchiveBytes: 1 });

    expect(existsSync(sibling)).toBe(true);
    expect(existsSync(notes)).toBe(true);
  });

  it('is a no-op when the active file does not exist', () => {
    const active = join(dir, 'hook-timing.jsonl');
    expect(() => rotateAnalyticsIfNeeded(active, { maxBytes: 1000 })).not.toThrow();
    expect(archives()).toEqual([]);
  });

  it('is a no-op for a path that is not a .jsonl', () => {
    const active = join(dir, 'hook-timing.log');
    writeSized(active, 5000);

    rotateAnalyticsIfNeeded(active, { maxBytes: 1000 });

    expect(existsSync(active)).toBe(true);
    expect(readdirSync(dir)).toEqual(['hook-timing.log']);
  });

  it('applies the 10 MB default cap when no options are supplied', () => {
    const active = join(dir, 'hook-timing.jsonl');
    writeSized(active, 2_000_000);

    rotateAnalyticsIfNeeded(active);

    expect(existsSync(active)).toBe(true); // 2 MB is under the 10 MB default
    expect(archives()).toEqual([]);
  });
});

describe('pruneArchives', () => {
  it('returns the paths it deleted, oldest first', () => {
    for (const [i, name] of ['hook-timing.2026-01.jsonl', 'hook-timing.2026-02.jsonl', 'hook-timing.2026-03.jsonl'].entries()) {
      const p = join(dir, name);
      writeSized(p, 100);
      setMtime(p, 1_000_000 + i * 1000);
    }

    const pruned = pruneArchives(dir, 'hook-timing', 1, Number.MAX_SAFE_INTEGER);

    expect(pruned.map((p) => p.split('/').pop())).toEqual([
      'hook-timing.2026-01.jsonl',
      'hook-timing.2026-02.jsonl',
    ]);
    expect(archives()).toEqual(['hook-timing.2026-03.jsonl']);
  });

  it('is a no-op when both caps already hold', () => {
    const p = join(dir, 'hook-timing.2026-01.jsonl');
    writeSized(p, 100);

    expect(pruneArchives(dir, 'hook-timing', 5, 10_000)).toEqual([]);
    expect(existsSync(p)).toBe(true);
  });
});
